import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const N=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/MEANS.md","filePath":"manual-zh/MEANS.md","lastUpdated":1785684581000}'),a={name:"manual-zh/MEANS.md"};function r(n,t,l,i,s,p){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h3 id="_15-11-means" tabindex="-1">15.11 MEANS <a class="header-anchor" href="#_15-11-means" aria-label="Permalink to &quot;15.11 MEANS&quot;">​</a></h3><pre><code>MEANS [TABLES =]
      {var_list}
        [ BY {var_list} [BY {var_list} [BY {var_list} … ]]]

      [ /{var_list}
         [ BY {var_list} [BY {var_list} [BY {var_list} … ]]] ]

      [/CELLS = [MEAN] [COUNT] [STDDEV] [SEMEAN] [SUM] [MIN] [MAX] [RANGE]
        [VARIANCE] [KURT] [SEKURT]
        [SKEW] [SESKEW] [FIRST] [LAST]
        [HARMONIC] [GEOMETRIC]
        [DEFAULT]
        [ALL]
        [NONE] ]

      [/MISSING = [INCLUDE] [DEPENDENT]]
</code></pre><p>你可以使用 <code>MEANS</code> 命令计算算术均值及类似统计量，既可以对整个数据集计算，也可以对数据的类别计算。</p><p>该命令最简单的形式为</p><pre><code>MEANS v.
</code></pre><p>它计算 v 的均值、计数和标准差。如果指定一个分组变量，例如</p><pre><code>MEANS v BY g.
</code></pre><p>则计算按 g 分组后 v 的均值、计数和标准差。除了均值、计数和标准差，你也可以指定你感兴趣的统计量：</p><pre><code>MEANS x y BY g
      /CELLS = HARMONIC SUM MIN.
</code></pre><p>此示例计算按 g 分组的 x 和 y 的调和均值、总和和最小值。</p><p><code>CELLS</code> 子命令指定要计算哪些统计量。可用的统计量有：</p><ul><li><code>MEAN</code> 算术均值。</li><li><code>COUNT</code> 取值的计数。</li><li><code>STDDEV</code> 标准差。</li><li><code>SEMEAN</code> 均值的标准误。</li><li><code>SUM</code> 取值的总和。</li><li><code>MIN</code> 最小值。</li><li><code>MAX</code> 最大值。</li><li><code>RANGE</code> 最大值与最小值之差。</li><li><code>VARIANCE</code> 方差。</li><li><code>FIRST</code> 类别中的第一个值。</li><li><code>LAST</code> 类别中的最后一个值。</li><li><code>SKEW</code> 偏度。</li><li><code>SESKEW</code> 偏度的标准误。</li><li><code>KURT</code> 峰度。</li><li><code>SEKURT</code> 峰度的标准误。</li><li><code>HARMONIC</code> 调和均值。</li><li><code>GEOMETRIC</code> 几何均值。</li></ul><p>此外，还识别三个特殊关键字：</p><ul><li><code>DEFAULT</code> 等同于 <code>MEAN</code> <code>COUNT</code> <code>STDDEV</code>。</li><li><code>ALL</code> 计算上述所有统计量。</li><li><code>NONE</code> 不计算任何统计量（仅显示摘要）。</li></ul><p>可以在单个命令中指定多个_表_（table）。每个表以‘/’分隔。例如</p><pre><code>MEANS TABLES =
      c d e BY x
      /a b BY x y
      /f BY y BY z.
</code></pre><p>包含三个表（‘TABLE =’是可选的）。第一个表有三个因变量 c、d 和 e，以及一个分类变量 x。第二个表有两个因变量 a 和 b，以及两个分类变量 x 和 y。第三个表有一个因变量 f，以及一个由 y 和 z 组合形成的分类变量。</p><p>默认情况下，只有在计算直接涉及的任何变量遇到缺失值（系统缺失或用户缺失）时，才会将该值从分析中省略。此行为可以通过 <code>/MISSING</code> 子命令修改。有三种可能的选项：<code>TABLE</code>、<code>INCLUDE</code> 和 <code>DEPENDENT</code>。</p><p><code>/MISSING = INCLUDE</code> 表示因变量或分类变量中的用户缺失值应按其表面值对待，而不被排除。</p><p><code>/MISSING = DEPENDENT</code> 表示因变量中的用户缺失值应按其表面值对待，但是具有分类变量用户缺失值的个案应从计算中省略。</p><h4 id="_15-11-1-example-means" tabindex="-1">15.11.1 Example Means <a class="header-anchor" href="#_15-11-1-example-means" aria-label="Permalink to &quot;15.11.1 Example Means&quot;">​</a></h4><p>repairs.sav 数据集包含由不同工厂生产、并在不同操作条件下试验的一组样本的平均故障间隔时间（<strong>mtbf</strong>）。由于分类变量有四种组合，仅通过查看数据列表，很难看出每个类别的分数如何变化。示例 15.4 展示了一种更易于理解的 <strong>mtbf</strong> 列表化方式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;repairs.sav&#39;.  means tables = mtbf       by factory by environment.</span></span></code></pre></div><p><strong>Example 15.4:</strong> 对 <strong>mtbf</strong> 分数按 <strong>factory</strong> 和 <strong>environment</strong> 类别运行 <code>MEANS</code></p><p>结果如 Result 15.3 所示。所示数字表示每个类别的均值、标准差和样本数。然而，这些数字并未表明结果是否在统计上显著。要做到这一点，你需要根据所检验的假设，使用 <code>ONEWAY</code>、<code>GLM</code> 或 <code>T-TEST</code> 过程。</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Percent</th><th>N</th><th>Percent</th><th>N</th><th>Percent</th></tr></thead><tbody><tr><td></td><td>Cases</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Included</td><td>Excluded</td><td>Total</td><td></td><td></td><td></td></tr><tr><td>mtbf * factory * environment</td><td>30</td><td>100.0%</td><td>0</td><td>.0%</td><td>30</td><td>100.0%</td></tr><tr><td>Manufacturing facility</td><td>Operating Environment</td><td>Mean</td><td>N</td><td>Std. Deviation</td><td></td><td></td></tr><tr><td>0</td><td>Temperate</td><td>7.26</td><td>9</td><td>2.57</td><td></td><td></td></tr><tr><td>Tropical</td><td>7.47</td><td>7</td><td>2.68</td><td></td><td></td><td></td></tr><tr><td>Total</td><td>7.35</td><td>16</td><td>2.53</td><td></td><td></td><td></td></tr><tr><td>1</td><td>Temperate</td><td>13.38</td><td>6</td><td>7.77</td><td></td><td></td></tr><tr><td>Tropical</td><td>8.20</td><td>8</td><td>8.39</td><td></td><td></td><td></td></tr><tr><td>Total</td><td>10.42</td><td>14</td><td>8.26</td><td></td><td></td><td></td></tr><tr><td>Total</td><td>Temperate</td><td>9.71</td><td>15</td><td>5.91</td><td></td><td></td></tr><tr><td>Tropical</td><td>7.86</td><td>15</td><td>6.20</td><td></td><td></td><td></td></tr><tr><td>Total</td><td>8.78</td><td>30</td><td>6.03</td><td></td><td></td><td></td></tr></tbody></table><p><strong>Result 15.3:</strong> 按 <strong>factory</strong> 和 <strong>environment</strong> 分类的 <strong>mtbf</strong></p><p>注意，可以计算统计量的变量数量没有限制，每层分类变量的数量没有限制，层的数量也没有限制。但是，对大量变量运行 <code>MEANS</code>，或使用包含大量不同取值的分类变量，可能会导致极其庞大的输出，难以解释。因此，你应该仔细考虑选择哪些变量参与分析。</p>`,28)])])}const S=d(a,[["render",r]]);export{N as __pageData,S as default};
